import time
class Redis:
    def __init__(s): s.d = {}
    def get(s, k):
        v = s.d.get(k)
        return v[0] if v and v[1] > time.time() else None
    def setex(s, k, t, v): s.d[k] = (v, time.time() + t)
    def delete(s, k): s.d.pop(k, None)
r = Redis()
DB = {7: "$100"}
def db_read(pid): return DB[pid]
def db_write(pid, p): DB[pid] = p
def get_product(pid):
